import pytest
from app.inventory_eval import Inventory

def test_inventory_initialization():
    inv = Inventory({'A': 10, 'B': 20})
    assert inv.snapshot() == {'A': 10, 'B': 20}

def test_inventory_reserve_success():
    inv = Inventory({'A': 10, 'B': 20})
    inv.reserve({'A': 5, 'B': 10})
    assert inv.snapshot() == {'A': 5, 'B': 10}

def test_inventory_reserve_insufficient_stock():
    inv = Inventory({'A': 10, 'B': 20})
    with pytest.raises(ValueError):
        inv.reserve({'A': 15, 'B': 25})
    assert inv.snapshot() == {'A': 10, 'B': 20}

def test_inventory_reserve_unknown_sku():
    inv = Inventory({'A': 10, 'B': 20})
    with pytest.raises(ValueError):
        inv.reserve({'C': 5})
    assert inv.snapshot() == {'A': 10, 'B': 20}

def test_inventory_reserve_empty_request():
    inv = Inventory({'A': 10, 'B': 20})
    inv.reserve({})
    assert inv.snapshot() == {'A': 10, 'B': 20}

def test_inventory_reserve_non_positive_quantity():
    inv = Inventory({'A': 10, 'B': 20})
    with pytest.raises(ValueError):
        inv.reserve({'A': 0, 'B': -5})
    assert inv.snapshot() == {'A': 10, 'B': 20}

def test_inventory_reserve_non_integer_quantity():
    inv = Inventory({'A': 10, 'B': 20})
    with pytest.raises(ValueError):
        inv.reserve({'A': 5.5, 'B': 10.0})
    assert inv.snapshot() == {'A': 10, 'B': 20}

def test_inventory_reserve_bool_quantity():
    inv = Inventory({'A': 10, 'B': 20})
    with pytest.raises(ValueError):
        inv.reserve({'A': True, 'B': False})
    assert inv.snapshot() == {'A': 10, 'B': 20}

