    with pytest.raises(ValueError):
        Inventory({'A': 10.5, 'B': 20})

def test_inventory_initialization_with_bools():
    with pytest.raises(ValueError):
        Inventory({'A': True, 'B': False})

def test_inventory_initialization_with_malformed_strings():
    with pytest.raises(ValueError):
        Inventory({'A': 'not a number', 'B': 20})

def test_inventory_reserve_malformed_string_quantity():
    inv = Inventory({'A': 10, 'B': 20})
    with pytest.raises(ValueError):
        inv.reserve({'A': 'not a number', 'B': 10})
    assert inv.snapshot() == {'A': 10, 'B': 20}

def test_inventory_reserve_nan_quantity():
    inv = Inventory({'A': 10, 'B': 20})
    with pytest.raises(ValueError):
        inv.reserve({'A': float('nan'), 'B': 10})
    assert inv.snapshot() == {'A': 10, 'B': 20}

def test_inventory_reserve_infinity_quantity():
    inv = Inventory({'A': 10, 'B': 20})
    with pytest.raises(ValueError):
        inv.reserve({'A': float('inf'), 'B': 10})
    assert inv.snapshot() == {'A': 10, 'B': 20}

def test_inventory_reserve_multiple_errors():
    inv = Inventory({'A': 10, 'B': 20})
    with pytest.raises(ValueError):
        inv.reserve({'C': 5, 'D': 10, 'A': -5, 'B': 0})
    assert inv.snapshot() == {'A': 10, 'B': 20}

