import pytest
from app.time_eval import normalize_timestamp


def test_normalize_timestamp_valid_utc() -> None:
    assert normalize_timestamp('2023-10-10T15:30:45Z') == '2023-10-10T15:30:45Z'


def test_normalize_timestamp_valid_offset() -> None:
    assert normalize_timestamp('2023-10-10T15:30:45+02:00') == '2023-10-10T13:30:45Z'


def test_normalize_timestamp_day_rollover() -> None:
    assert normalize_timestamp('2023-10-10T23:30:45+02:00') == '2023-10-10T21:30:45Z'


def test_normalize_timestamp_invalid_naive() -> None:
    with pytest.raises(ValueError):
        normalize_timestamp('2023-10-10T15:30:45')


def test_normalize_timestamp_invalid_string() -> None:
    with pytest.raises(ValueError):
        normalize_timestamp('invalid-date')


def test_normalize_timestamp_non_string_input() -> None:
    with pytest.raises(ValueError):
        normalize_timestamp(12345)

